changeSet.sql:
DO $$
DECLARE
    r           record;
    v_scanned   integer := 0;
    v_corrected integer := 0;
    v_forced_t  boolean;
    v_forced_a  boolean;
BEGIN
    SELECT relforcerowsecurity INTO v_forced_t
      FROM pg_class WHERE oid = 'nexus.topics'::regclass;
    SELECT relforcerowsecurity INTO v_forced_a
      FROM pg_class WHERE oid = 'nexus.topic_assignments'::regclass;

    IF v_forced_t THEN
        ALTER TABLE nexus.topics NO FORCE ROW LEVEL SECURITY;
    END IF;
    IF v_forced_a THEN
        ALTER TABLE nexus.topic_assignments NO FORCE ROW LEVEL SECURITY;
    END IF;

    FOR r IN
        SELECT t.tenant_id, t.id, t.doc_count, COALESCE(a.cnt, 0) AS actual_count
          FROM nexus.topics t
          LEFT JOIN (
              SELECT tenant_id, topic_id, COUNT(*) AS cnt
                FROM nexus.topic_assignments
               GROUP BY tenant_id, topic_id
          ) a ON a.tenant_id = t.tenant_id AND a.topic_id = t.id
         ORDER BY t.tenant_id, t.id
    LOOP
        v_scanned := v_scanned + 1;
        IF r.doc_count IS DISTINCT FROM r.actual_count THEN
            UPDATE nexus.topics
               SET doc_count = r.actual_count
             WHERE tenant_id = r.tenant_id AND id = r.id;
            v_corrected := v_corrected + 1;
            RAISE NOTICE 'hygiene-007-1: topic %.% doc_count corrected % -> % (drift predates taxonomy-013 or came through the fidelity import)',
                r.tenant_id, r.id, r.doc_count, r.actual_count;
        END IF;
    END LOOP;

    IF v_forced_a THEN
        ALTER TABLE nexus.topic_assignments FORCE ROW LEVEL SECURITY;
    END IF;
    IF v_forced_t THEN
        ALTER TABLE nexus.topics FORCE ROW LEVEL SECURITY;
    END IF;

    RAISE NOTICE 'hygiene-007-1: % topic(s) scanned in schema nexus, % doc_count corrected', v_scanned, v_corrected;
END $$;
